Class Termostato
  Private Define grados As Integer;

  Method Constructor()
    This.grados <- 20;
  EndMethod

  Method Subir()
    If This.grados < 30 Then
      This.grados <- This.grados + 1;
    EndIf
  EndMethod

  Method Bajar()
    If This.grados > 16 Then
      This.grados <- This.grados - 1;
    EndIf
  EndMethod

  Method Grados() As Integer
    Return This.grados;
  EndMethod
EndClass

Algorithm Aula
  Define aparato As Termostato <- New Termostato();
  Define orden As String;
  Read orden;
  While orden <> "fin" Do
    If orden = "+" Then
      aparato.Subir();
    Else
      aparato.Bajar();
    EndIf
    Read orden;
  EndWhile
  Write aparato.Grados();
EndAlgorithm
